const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

/** Ticks once per `ms` so relative timestamps ("2m ago") don't rot on screen. */
const useClockTick = (ms) => {
  const [, setTick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTick((t) => t + 1), ms);
    return () => clearInterval(id);
  }, [ms]);
};

// Animated Counter Hook — counts from the previous value, so a background
// refresh nudges the number instead of replaying from zero.
const useAnimatedCounter = (end, duration = 900) => {
  const [count, setCount] = useState(end);
  const frameRef = useRef(null);
  const fromRef = useRef(end);

  useEffect(() => {
    const from = fromRef.current;
    if (from === end || prefersReducedMotion()) {
      fromRef.current = end;
      setCount(end);
      return undefined;
    }

    let startTime;
    const animate = (timestamp) => {
      if (!startTime) startTime = timestamp;
      const progress = Math.min((timestamp - startTime) / duration, 1);
      const easeOutQuart = 1 - Math.pow(1 - progress, 4);
      setCount(Math.round(from + (end - from) * easeOutQuart));
      if (progress < 1) {
        frameRef.current = requestAnimationFrame(animate);
      } else {
        fromRef.current = end;
      }
    };

    frameRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(frameRef.current);
  }, [end, duration]);

  return count;
};

// Animated Number Component
const AnimatedNumber = ({ value, suffix = "" }) => {
  const animatedValue = useAnimatedCounter(value);
  return (
    <span>
      {animatedValue.toLocaleString()}
      {suffix}
    </span>
  );
};

// Mini Sparkline Chart Component
const SparklineChart = React.memo(({ data, color, height = 40 }) => {
  if (!data || data.length < 2) return null;

  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;

  const points = data
    .map((value, index) => {
      const x = (index / (data.length - 1)) * 100;
      const y = height - ((value - min) / range) * height;
      return `${x},${y}`;
    })
    .join(" ");

  const areaPoints = `0,${height} ${points} 100,${height}`;
  const gradientId = `spark-${color.replace("#", "")}`;

  return (
    <svg
      viewBox={`0 0 100 ${height}`}
      className="sparkline-chart"
      preserveAspectRatio="none"
    >
      <defs>
        <linearGradient id={gradientId} x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor={color} stopOpacity="0.3" />
          <stop offset="100%" stopColor={color} stopOpacity="0" />
        </linearGradient>
      </defs>
      <polygon
        points={areaPoints}
        fill={`url(#${gradientId})`}
        className="sparkline-area"
      />
      <polyline
        points={points}
        fill="none"
        stroke={color}
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        className="sparkline-line"
      />
      <circle
        cx="100"
        cy={height - ((data[data.length - 1] - min) / range) * height}
        r="3"
        fill={color}
        className="sparkline-dot"
      />
    </svg>
  );
});

// Donut Chart Component
const DonutChart = React.memo(({ data }) => {
  const segments = useMemo(() => {
    const items = (data || []).filter((d) => d.value > 0);
    const total = items.reduce((sum, item) => sum + item.value, 0);
    if (!total) return { total: 0, items: [] };

    const radius = 40;
    const circumference = 2 * Math.PI * radius;
    let offsetAngle = 0;

    return {
      total,
      items: items.map((item, index) => {
        const percentage = (item.value / total) * 100;
        const rotation = offsetAngle - 90;
        offsetAngle += (percentage / 100) * 360;
        return {
          ...item,
          percentage,
          rotation,
          strokeDasharray: `${(percentage / 100) * circumference} ${circumference}`,
          delay: index * 0.1,
        };
      }),
    };
  }, [data]);

  if (!segments.total) return <EmptyPanel message="No visitor types yet" />;

  return (
    <div className="donut-chart-container">
      <svg viewBox="0 0 100 100" className="donut-chart">
        {segments.items.map((segment) => (
          <circle
            key={segment.label}
            cx="50"
            cy="50"
            r="40"
            fill="none"
            stroke={segment.color}
            strokeWidth="12"
            strokeDasharray={segment.strokeDasharray}
            strokeLinecap="round"
            className="donut-segment"
            style={{
              transform: `rotate(${segment.rotation}deg)`,
              transformOrigin: "50% 50%",
              animationDelay: `${segment.delay}s`,
            }}
          >
            <title>{`${segment.label}: ${segment.value} (${Math.round(
              segment.percentage
            )}%)`}</title>
          </circle>
        ))}
        <text x="50" y="46" textAnchor="middle" className="donut-total">
          {segments.total}
        </text>
        <text x="50" y="58" textAnchor="middle" className="donut-label">
          Total
        </text>
      </svg>
      <div className="donut-legend">
        {segments.items.map((segment) => (
          <div key={segment.label} className="legend-item">
            <span
              className="legend-color"
              style={{ background: segment.color }}
            ></span>
            <span className="legend-label">{segment.label}</span>
            <span className="legend-value">{segment.value}</span>
          </div>
        ))}
      </div>
    </div>
  );
});

