// Activity Heatmap Component — day-of-week x hour, from real visit timestamps
const ActivityHeatmap = React.memo(({ data }) => {
  const hours = useMemo(() => Array.from({ length: 24 }, (_, i) => i), []);
  const max = useMemo(
    () => Math.max(1, ...data.flatMap((row) => row)),
    [data]
  );
  const hasData = useMemo(
    () => data.some((row) => row.some((cell) => cell > 0)),
    [data]
  );

  if (!hasData) return <EmptyPanel message="No visit times recorded yet" />;

  return (
    <div className="heatmap-container">
      <div className="heatmap-hours">
        {hours
          .filter((_, i) => i % 4 === 0)
          .map((hour) => (
            <span key={hour}>{hour}h</span>
          ))}
      </div>
      <div className="heatmap-grid">
        {DAYS.map((day, dayIndex) => (
          <div key={day} className="heatmap-row">
            <span className="heatmap-day">{day}</span>
            <div className="heatmap-cells">
              {hours.map((hour) => {
                const count = data[dayIndex][hour];
                return (
                  <div
                    key={hour}
                    className="heatmap-cell"
                    style={{ "--intensity": count / max }}
                    title={`${day} ${hour}:00 — ${count} visit${
                      count === 1 ? "" : "s"
                    }`}
                  />
                );
              })}
            </div>
          </div>
        ))}
      </div>
      <div className="heatmap-legend">
        <span>0</span>
        <div className="legend-gradient"></div>
        <span>{max}</span>
      </div>
    </div>
  );
});

